+  margin-left: auto;
+  margin-right: auto;
+}
+
+/* Product Cards & Grids */
+.section-title {
+  font-size: 2rem;
+  margin-bottom: var(--spacing-lg);
+}
+
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
