+  position: absolute;
+  inset: 0;
+}
+
+.product-card .btn {
+  position: relative;
+  z-index: 2;
+  margin-top: auto;
+}
+
+.product-price {
+  margin-bottom: var(--spacing-md);
+  display: flex;
+  gap: var(--spacing-sm);
+  align-items: center;
+}
+
+.price-current {
+  font-weight: bold;
+  font-size: 1.125rem;
+}
+
+.price-original {
+  color: var(--text-muted);
+  font-size: 0.875rem;
+}
+
+/* Deals Section */
+.deals-header {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  margin-bottom: var(--spacing-lg);
+  flex-wrap: wrap;
+  gap: var(--spacing-md);
+}
+
+.deals-header .section-title {
+  margin-bottom: 0;
+}
+
+.view-all {
+  font-weight: 500;
+  text-decoration: none;
+}
+
+/* Editorial Section */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
+  gap: var(--spacing-lg);
+}
+
+.editorial-card {
+  background-color: var(--bg-light);
+  border-radius: 8px;
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+}
+
+.editorial-img {
+  width: 100%;
+  aspect-ratio: 16/9;
+  object-fit: cover;
+}
+
+.editorial-content {
+  padding: var(--spacing-lg);
+  display: flex;
+  flex-direction: column;
+  flex-grow: 1;
+}
+
+.editorial-content h3 {
+  font-size: 1.5rem;
+  margin-bottom: var(--spacing-sm);
+}
+
+.editorial-content p {
+  color: var(--text-muted);
+  margin-bottom: var(--spacing-lg);
+  flex-grow: 1;
