+  outline-offset: 2px;
+}
+
+.footer-bottom {
+  border-top: 1px solid var(--secondary-color);
+  padding-top: var(--spacing-md);
+  text-align: center;
+  color: #cbd5e1;
+  font-size: 0.875rem;
+}
+
+/* Responsive adjustments */
+@media (max-width: 768px) {
+  .header-inner {
+    flex-direction: column;
+    align-items: flex-start;
+  }
+  
+  .nav-links {
+    width: 100%;
